import { useState } from 'react';
import { verifySingle } from '../api';

const CheckRow = ({ label, value, type }) => {
  const getDisplay = () => {
    if (type === 'smtp') {
      if (value === true) return '250 OK';
      if (value === false) return 'Rejected';
      return 'Timeout';
    }
    if (type === 'bool-bad') return value ? 'Yes' : 'No';
    if (type === 'bool') return value ? 'Valid' : 'Invalid';
    return value;
  };

  const getBadgeClass = () => {
    if (type === 'risk') return `badge badge-${value?.toLowerCase()}`;
    if (type === 'smtp') {
      if (value === true) return 'badge badge-valid';
      if (value === false) return 'badge badge-invalid';
      return 'badge badge-null';
    }
    if (type === 'bool-bad') return value ? 'badge badge-high' : 'badge badge-valid';
    return value ? 'badge badge-valid' : 'badge badge-invalid';
  };

  return (
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '11px 0', borderBottom: '1px solid var(--border)' }}>
      <span style={{ color: 'var(--text-muted)', fontSize: 13 }}>{label}</span>
      <span className={getBadgeClass()}>{getDisplay()}</span>
    </div>
  );
};

export default function SingleCheck() {
  const [email, setEmail] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  const handleVerify = async () => {
    if (!email.trim()) return;
    setLoading(true);
    setError('');
    setResult(null);
    try {
      const data = await verifySingle(email.trim());
      setResult(data);
    } catch {
      setError('Could not reach the API. Make sure the backend is running on port 8000.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <div style={{ marginBottom: 24 }}>
        <h2 style={{ fontSize: 18, fontWeight: 700, marginBottom: 6, letterSpacing: '-0.02em' }}>Single email check</h2>
        <p style={{ color: 'var(--text-muted)', fontSize: 13 }}>Full SMTP handshake + MX lookup + risk score. Takes 3–10 seconds.</p>
      </div>

      <div style={{ display: 'flex', gap: 10, marginBottom: 20 }}>
        <input
          type="email"
          placeholder="john@company.com"
          value={email}
          onChange={e => setEmail(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && handleVerify()}
          style={{ flex: 1 }}
        />
        <button className="btn-primary" onClick={handleVerify} disabled={loading || !email.trim()} style={{ whiteSpace: 'nowrap', minWidth: 110 }}>
          {loading ? <><span className="spinner" style={{ marginRight: 6 }}>↻</span>Checking</> : 'Verify →'}
        </button>
      </div>

      {loading && (
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '14px 16px', background: 'var(--bg3)', borderRadius: 'var(--radius)', fontSize: 13, color: 'var(--text-muted)' }}>
          <span className="spinner">↻</span>
          Running SMTP handshake — this can take a few seconds...
        </div>
      )}

      {error && (
        <div style={{ background: 'var(--red-bg)', border: '1.5px solid var(--red-border)', borderRadius: 'var(--radius)', padding: '12px 16px', color: 'var(--red)', fontSize: 13 }}>
          {error}
        </div>
      )}

      {result && (
        <div className="animate-in" style={{ marginTop: 4 }}>
          {/* Result header */}
          <div style={{ background: 'var(--bg3)', border: '1.5px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '18px 20px', marginBottom: 16, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <div>
              <div className="mono" style={{ fontSize: 14, fontWeight: 500, color: 'var(--text)', marginBottom: 3 }}>{result.email}</div>
              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{result.message}</div>
            </div>
            <div style={{ textAlign: 'right' }}>
              <span className={`badge badge-${result.risk?.toLowerCase()}`} style={{ fontSize: 12, padding: '5px 13px' }}>
                {result.risk} RISK
              </span>
            </div>
          </div>

          {/* Check rows */}
          <div style={{ background: 'var(--bg2)', border: '1.5px solid var(--border)', borderRadius: 'var(--radius-lg)', padding: '4px 20px', boxShadow: 'var(--shadow)' }}>
            <CheckRow label="Format" value={result.format_valid} type="bool" />
            <CheckRow label="MX records" value={result.mx_valid} type="bool" />
            <CheckRow label="SMTP response" value={result.smtp_valid} type="smtp" />
            <CheckRow label="Catch-all domain" value={result.catch_all} type="bool-bad" />
            <CheckRow label="Disposable" value={result.disposable} type="bool-bad" />
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '11px 0' }}>
              <span style={{ color: 'var(--text-muted)', fontSize: 13 }}>Role-based</span>
              <span className={result.role_based ? 'badge badge-null' : 'badge badge-valid'}>
                {result.role_based ? 'Yes' : 'No'}
              </span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
